{
  "description": "The creature is a quadrupedal, bear-bodied animal shown in right-facing profile against a plain light background. Its entire body except for the dorsal midline is covered in long, shaggy brown fur that is darker on the legs and lighter on the muzzle and sides. The head is bear-like with a blunt muzzle, dark nose, and small eyes. A single large, glossy, dark reddish-black curved horn with a side tine rises from the forehead. Behind the head, the neck and shoulders are covered by a glossy, domed, dark reddish-brown plate with pointed lateral projections, and the back from behind the shoulders to the rump is covered by a large, oval, glossy dark brown shell with fine longitudinal ridges and a thin dark rim. Along the lower edge of the shell where it meets the fur, a row of small circular openings is visible. The animal stands on four thick furry legs ending in clawed paws and has a very short furry stub tail at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with dense brown fur, a lighter brown muzzle, a large black nose at the tip, small dark brown eyes, and a slightly open mouth",
      "where": "at the front right end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one large, smooth, glossy dark reddish-black horn that curves upward and backward with a single sharp forward-pointing prong on its front edge, with a glossy base encircling the forehead",
      "where": "arising from the center of the forehead on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on top of the head behind the horn, one more forward and one slightly behind"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred brown legs with long shaggy hair, muscular in appearance",
      "where": "two forelegs under the chest at the front and two hind legs under the hips at the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dark pads and five long, curved, light tan claws on each",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, stubby, furry brown tail",
      "where": "protruding from the rear left end of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large, oval, highly glossy domed dark brown shell with fine parallel longitudinal ridges and a thin black outer rim, resembling beetle elytra",
      "where": "covering the dorsal surface from the mid-back to the rump, over the fur"
    },
    {
      "part": "plates",
      "looks_like": "a glossy, domed, dark reddish-brown plate with three pointed lateral projections on each side and a smooth reflective surface, resembling a beetle pronotum",
      "where": "covering the shoulder and upper back area immediately behind the head and in front of the larger shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
